import math
import re

_LABEL = re.compile(r"[A-Z]{1,3}\Z")


def render_waypoints(source):
    if not isinstance(source, str):
        raise TypeError("source must be a string")
    lines = source.splitlines()
    if len(lines) < 2:
        raise ValueError("missing header")
    if not re.fullmatch(r"[0-9]+", lines[0]):
        raise ValueError("invalid count")
    count = int(lines[0])
    title = lines[1]
    if not title:
        raise ValueError("blank title")
    body = lines[2:]
    if len(body) < count:
        raise ValueError("count mismatch")
    records = body[:count]
    if any(not line.strip() for line in records):
        raise ValueError("blank record")
    if any(line.strip() for line in body[count:]):
        raise ValueError("extra content")
    output = ["ROUTE " + title]
    for line in records:
        fields = line.split()
        if len(fields) != 4 or _LABEL.fullmatch(fields[0]) is None:
            raise ValueError("malformed record")
        try:
            coordinates = [float(value) for value in fields[1:]]
        except ValueError as exc:
            raise ValueError("malformed coordinate") from exc
        if not all(math.isfinite(value) for value in coordinates):
            raise ValueError("non-finite coordinate")
        output.append(
            "{} {:.3f} 1 {:.3f} 1 {:.3f} 0".format(fields[0], *coordinates)
        )
    return "\n".join(output) + "\n"

